sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 anchor;
uniform float zoomBase;
uniform float speed;
uniform float rotationSpeed;
uniform float twist;
uniform float tile;
uniform float shutter;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
float4 shot(float2 coord, float T) {
    float s = pow(zoomBase, T * speed);
    float2 anc = anchor * size;
    float2 d = (coord - anc) / s;
    float r = length(coord - anc) / length(size);
    d = rot2(d, -radians(rotationSpeed) * T - twist * r);
    float2 q = anc + d;
    if (tile > 0.5) q = mod(q, size);
    return texT(q);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 acc = float4(0.0);
    for (int i = 0; i < 8; i++) {
        acc += shot(coord, time - shutter * 0.04 * float(i) / 7.0);
    }
    return fin(c, acc / 8.0, opacity);
}
